(async()=>{
const sleep=ms=>new Promise(r=>setTimeout(r,ms)); const out=[]; const ok=(k,c,x)=>out.push((c?'PASS ':'FAIL ')+k+(c?'':' '+JSON.stringify(x)))
const S=()=>window.__koogState()
const PF=await import('/src/profile/profile.ts'), D=await import('/src/layout/docks.ts'), M=await import('/src/music/masterClock.ts')
const LD=await import('/src/features/loopstation/LoopsDock.tsx'), KD=await import('/src/features/kode/kodeDock.ts'), LS=await import('/src/features/loopstation/loopSurface.ts')
const G=await import('/src/music/guide.ts'), SC=await import('/src/music/scoreStore.ts'), L=await import('/src/features/loopstation/loopEngine.ts')
const R=await import('/src/features/games/racer/engine.ts'), MEM=await import('/src/features/games/memory/engine.ts'), SL=await import('/src/music/sheetLevel.ts')
const invariants=(label)=>{ const s=S(); ok(label+': at most one bottom dock', D.openDocks('bottom').length<=1, D.openDocks('bottom')); ok(label+': clock stopped when nobody holds it and nothing runs', !(s.clock.running && s.clock.holders.length===0 && !s.loop.running && !s.drums.running && !s.kode.running) || 'player-started', s.clock) }
ok('inspector exists', typeof window.__koogState==='function')
const base=S().subscriptions
// --- profiles: two kids, per-player data reloads
const P=PF.useProfile.getState(); if(!P.profiles.includes('zed')) P.create('zed',false); if(!P.profiles.includes('yan')) P.create('yan',false)
P.signIn('zed'); SL.setSheetLevel('full'); PF.psave('racer',{v:1,stars:{t1:3},best:{},vehicle:'car',mode:'keys',streak:0,bestStreak:0,laps:4}); PF.psave('memory',{best:{},plays:7})
P.signIn('yan'); await sleep(100)
ok('yan: sheet level is his own', SL.useSheetLevel.getState().level==='single', SL.useSheetLevel.getState().level)
ok('yan: racer save is his own (not zed\'s 4 laps)', (R.useRacer.getState().save.laps||0)===0, R.useRacer.getState().save)
ok('yan: memory save is his own', MEM.useMemory.getState().save.plays===0, MEM.useMemory.getState().save)
P.signIn('zed'); await sleep(100)
ok('zed: racer save comes back', R.useRacer.getState().save.laps===4, R.useRacer.getState().save)
ok('zed: sheet level comes back', SL.useSheetLevel.getState().level==='full')
ok('profile listeners are named, count stable', S().profile.listeners.names.length>=8, S().profile.listeners)
// --- docks in sequence
for (const step of ['looper','kode','drums','looper','drums','kode']) {
  if(step==='looper') LD.setLoopsDock(true); if(step==='kode') KD.setKodeDock(true); if(step==='drums') LS.setControllerPage('drums')
  await sleep(150); invariants('dock '+step); ok('dock '+step+' is the one open', D.openDocks('bottom').join()===step, D.openDocks('bottom'))
}
D.closeAllDocks(); await sleep(100)
// --- screens and games: leaks after leaving
for (const g of ['zombies','jiujitsu','fashion','memory','feast','tree','racer','bachdoom']) {
  location.hash='#/games/'+g; await sleep(1100)
  location.hash='#/play'; await sleep(700)
  const s=S(); ok('left '+g+': no lingering glow', s.guide.lit===0, s.guide); ok('left '+g+': no sheet score from a game', !s.sheet.scoreOwner || s.sheet.scoreOwner==='songs'&&false, s.sheet.scoreOwner); ok('left '+g+': no metronome', !s.loop.metronome); invariants('left '+g)
}
for (const sc of ['songs','challenges','beats','synth','log','play']) { location.hash='#/'+sc; await sleep(600); invariants('screen '+sc) }
// --- clock ownership
M.stopMaster(); M.acquireClock('racer'); M.acquireClock('drums'); M.releaseClock('racer'); ok('clock: drums still holds it', M.isRunning()); M.releaseClock('drums'); ok('clock: stops with the last holder', !M.isRunning())
G.setGuideFor('a',[60]); G.setGuideFor('b',[62]); G.clearGuideFor('a'); ok('guide: stale clear ignored', G.useGuide.getState().targets[0]===62); G.clearGuideFor('b')
// --- no duplicate subscriptions after all that navigation (remounts)
const now=S().subscriptions; ok('note listeners did not grow', now.notes<=base.notes+2, {base:base.notes, now:now.notes}); ok('judge listeners did not grow', now.judge<=base.judge+2, {base:base.judge, now:now.judge}); ok('panic targets did not grow', now.panicTargets<=base.panicTargets+3, {base:base.panicTargets, now:now.panicTargets})
P.signOut()
const bad=out.filter(x=>x.startsWith('FAIL')); return 'state harness: '+(out.length-bad.length)+' pass, '+bad.length+' fail'+(bad.length?'\n'+bad.join('\n'):'')
})()
